"""TRF015: Models declaring tied weights must expose a tie_word_embeddings config flag."""

import ast
from pathlib import Path

from ._helpers import (
    Violation,
    _class_methods,
    _function_argument_names,
    _get_class_assignments,
    _has_rule_suppression,
    _is_direct_pretrained_config_subclass,
    _simple_name,
    full_name,
    iter_pretrained_classes,
)


RULE_ID = ""  # Set by discovery

_PRETRAINED_CONFIG_NAMES = {"PreTrainedConfig", "PretrainedConfig"}


def check(tree: ast.Module, file_path: Path, source_lines: list[str]) -> list[Violation]:
    # Only modeling/modular files declare models; config classes live in companion files.
    from .mlinter import _find_companion_files

    if not file_path.name.startswith(("modeling_", "modular_")):
        return []

    tied_models = [
        node
        for node in iter_pretrained_classes(tree, source_lines, RULE_ID)
        if _has_non_empty_tied_weights(node)
    ]
    if not tied_models:
        return []

    config_classes = _collect_config_classes(_find_companion_files(file_path))
    if not config_classes:
        return []

    model_classes = {node.name: node for node in tree.body if isinstance(node, ast.ClassDef)}

    violations: list[Violation] = []
    for model_node in tied_models:
        config_node = _resolve_config_class(model_node, config_classes, model_classes)
        if config_node is None:
            continue
        # A config that derives from another *Config already inherits the flag from its parent.
        if _inherits_other_config(config_node):
            continue
        if _config_declares_tie_word_embeddings(config_node):
            continue

        violations.append(
            Violation(
                file_path=file_path,
                line_number=model_node.lineno,
                message=(
                    f"{RULE_ID}: {model_node.name} declares tied weights (_tied_weights_keys) but its config "
                    f"class {config_node.name} does not expose a tie_word_embeddings flag to disable weight tying."
                ),
            )
        )

    return violations


def _has_non_empty_tied_weights(class_node: ast.ClassDef) -> bool:
    value = _get_class_assignments(class_node).get("_tied_weights_keys")
    if value is None:
        return False
    if isinstance(value, (ast.List, ast.Tuple, ast.Set)):
        return len(value.elts) > 0
    if isinstance(value, ast.Dict):
        return len(value.keys) > 0
    if isinstance(value, ast.Constant) and value.value is None:
        return False
    # Any other expression (comprehension, call, name, ...) is treated as potentially non-empty.
    return True


def _collect_config_classes(companion_files: list[Path]) -> dict[str, ast.ClassDef]:
    """Map config class name -> ClassDef across companion files, preferring earlier (suffix-matched) files."""
    config_classes: dict[str, ast.ClassDef] = {}
    for config_path in companion_files:
        try:
            config_tree = ast.parse(config_path.read_text(encoding="utf-8"), filename=str(config_path))
        except (OSError, SyntaxError, ValueError):
            continue
        for node in config_tree.body:
            if isinstance(node, ast.ClassDef) and _is_config_like(node):
                config_classes.setdefault(node.name, node)
    return config_classes


def _is_config_like(class_node: ast.ClassDef) -> bool:
    return class_node.name.endswith("Config") or _is_direct_pretrained_config_subclass(class_node)


def _resolve_config_class(
    model_node: ast.ClassDef,
    config_classes: dict[str, ast.ClassDef],
    model_classes: dict[str, ast.ClassDef],
) -> ast.ClassDef | None:
    # config_class / config annotations may be declared on a base PreTrainedModel class, so we
    # walk the in-file inheritance chain (the model class first, then its ancestors).
    lineage = _self_and_ancestors(model_node, model_classes)

    # 1. Explicit `config_class = SomeConfig` assignment.
    for cls in lineage:
        config_value = _get_class_assignments(cls).get("config_class")
        if isinstance(config_value, (ast.Name, ast.Attribute)):
            name = _simple_name(full_name(config_value))
            if name in config_classes:
                return config_classes[name]

    # 2. `config: SomeConfig` type annotation (class-level or __init__ parameter).
    for cls in lineage:
        annotated = _annotated_config_name(cls)
        if annotated is not None and annotated in config_classes:
            return config_classes[annotated]

    # 3. Longest shared prefix between model class and config class names.
    best_node: ast.ClassDef | None = None
    best_len = 0
    for config_name, config_node in config_classes.items():
        shared = _shared_prefix_len(model_node.name, config_name)
        if shared > best_len:
            best_len = shared
            best_node = config_node
    return best_node


def _self_and_ancestors(model_node: ast.ClassDef, model_classes: dict[str, ast.ClassDef]) -> list[ast.ClassDef]:
    ordered: list[ast.ClassDef] = []
    visited: set[str] = set()

    def visit(name: str) -> None:
        if name in visited:
            return
        visited.add(name)
        node = model_classes.get(name)
        if node is None:
            return
        ordered.append(node)
        for base in node.bases:
            try:
                visit(_simple_name(full_name(base)))
            except ValueError:
                continue

    visit(model_node.name)
    return ordered


def _annotated_config_name(model_node: ast.ClassDef) -> str | None:
    for item in model_node.body:
        if (
            isinstance(item, ast.AnnAssign)
            and isinstance(item.target, ast.Name)
            and item.target.id == "config"
            and isinstance(item.annotation, (ast.Name, ast.Attribute))
        ):
            return _simple_name(full_name(item.annotation))

    init = _class_methods(model_node).get("__init__")
    if init is not None:
        for arg in list(init.args.args) + list(init.args.kwonlyargs):
            if arg.arg == "config" and isinstance(arg.annotation, (ast.Name, ast.Attribute)):
                return _simple_name(full_name(arg.annotation))
    return None


